for f in \
  "/sdcard/Nexus_Brain/nexus_vault/03_pricing_offers/Companion_to_Master_Pricing_And_Offer_Design.md" \
  "/sdcard/Nexus_Brain/nexus_vault/03_pricing_offers/Master_Pricing_And_Offer_Design.md"; do
  base=$(basename "$f")
  sec18=$(grep -n '^## §18' "$f" | head -1 | cut -d: -f1)
  body_end=$((sec18 - 1))
  echo "=== $base ==="
  concepts=$(sed -n "${sec18},\$p" "$f" | grep -oP '\[\[Concept_\K[^\]]+' | sort -u)
  for c in $concepts; do
    result=$(check_concept_in_body "$f" "$c" "$body_end")
    if [ "$result" = "NOT_FOUND" ]; then
      echo "  MISSING: $c"
    fi
  done
  echo ""
done

